#include <Arduino.h>
const int SHCP_PIN = A2;
const int STCP_PIN = A1;
const int DS_PIN = A0;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentNumber = 0;
bool ledState = false;

void setup();
void loop();
void displayNumber(int num);
void updateBarGraph(int segments);
void setup() {
  for (int i = 2; i <= 13; i++) pinMode(i, OUTPUT);  
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  displayNumber(0);
  updateBarGraph(1);
}
void loop() {
  delay(2000);
  currentNumber = (currentNumber + 1) % 100;
  displayNumber(currentNumber);
  updateBarGraph((currentNumber / 10) + 1);
  ledState = !ledState;
  digitalWrite(2, ledState ? HIGH : LOW);  
  digitalWrite(3, !ledState ? HIGH : LOW); 
}
void displayNumber(int num) {
  byte tensCode = segmentCodes[num / 10];
  byte unitsCode = segmentCodes[num % 10];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, unitsCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void updateBarGraph(int segments) {
  for (int i = 4; i <= 13; i++) {  
    digitalWrite(i, (i < 4 + segments) ? HIGH : LOW);
  }
}
